from copy import deepcopy
from enum import Enum


class Lifecycle(Enum):
    ACTIVE = "active"
    RETIRED = "retired"


def _text(value: str, field: str) -> str:
    if not isinstance(value, str) or not value.strip():
        raise ValueError(f"{field} must be a non-empty string")
    return value


class Patron:
    def __init__(self, serial: str, first_name: str, last_name: str, birth_date: str):
        self._serial = _text(serial, "serial")
        self.update_name(first_name, last_name)
        self.update_birth_date(birth_date)

    @property
    def identifier(self) -> str:
        return "Patron:" + self._serial

    def update_name(self, first_name: str, last_name: str) -> None:
        new_first_name = _text(first_name, "first_name")
        new_last_name = _text(last_name, "last_name")
        self.first_name = new_first_name
        self.last_name = new_last_name

    def update_birth_date(self, value: str) -> None:
        self.birth_date = _text(value, "birth_date")


class Curator:
    def __init__(self, serial: str, first_name: str, last_name: str):
        self._serial = _text(serial, "serial")
        self.update_name(first_name, last_name)

    @property
    def identifier(self) -> str:
        return "Curator:" + self._serial

    def update_name(self, first_name: str, last_name: str) -> None:
        new_first_name = _text(first_name, "first_name")
        new_last_name = _text(last_name, "last_name")
        self.first_name = new_first_name
        self.last_name = new_last_name


class Collection:
    def __init__(self):
        self._patrons = []
        self._curators = []
        self.lifecycle = Lifecycle.ACTIVE

    @staticmethod
    def _add(items, value, expected):
        if not isinstance(value, expected):
            raise TypeError("incorrect member type")
        if any(item.identifier == value.identifier for item in items):
            raise ValueError("duplicate identifier")
        items.append(value)

    @staticmethod
    def _remove(items, value, expected):
        if not isinstance(value, expected):
            raise TypeError("incorrect member type")
        identifier = value.identifier
        for index, item in enumerate(items):
            if item.identifier == identifier:
                del items[index]
                return True
        return False

    def add_patron(self, value: Patron) -> None:
        self._add(self._patrons, value, Patron)

    def add_curator(self, value: Curator) -> None:
        self._add(self._curators, value, Curator)

    def remove_patron(self, value: Patron) -> bool:
        return self._remove(self._patrons, value, Patron)

    def remove_curator(self, value: Curator) -> bool:
        return self._remove(self._curators, value, Curator)

    def snapshot(self) -> dict:
        return {"patrons": list(self._patrons), "curators": list(self._curators)}

    def update_lifecycle(self, status: Lifecycle) -> None:
        if not isinstance(status, Lifecycle):
            raise TypeError("status must be a Lifecycle")
        self.lifecycle = status

